mapper.update:
UPDATE afv_media_job SET status = 'WAITING', phase = '等待原预览接收完成', owner_instance_id = NULL,
    lease_until = NULL, next_run_at = TIMESTAMPADD(SECOND, 5, UTC_TIMESTAMP(6)), revision = revision + 1,
    updated_at = UTC_TIMESTAMP(6) WHERE id = #{id}

UPDATE afv_media_job SET status = 'RUNNING', owner_instance_id = #{owner}, owner_epoch = owner_epoch + 1,
    lease_until = TIMESTAMPADD(SECOND, 90, UTC_TIMESTAMP(6)), revision = revision + 1, updated_at = UTC_TIMESTAMP(6)
WHERE id = #{id}

mapper.select:
SELECT n.id FROM afv_canvas_node_run n JOIN afv_canvas_run r ON r.id = n.run_id
WHERE n.id = #{nodeRunId} AND n.external_kind = 'MEDIA_IMPORT' AND n.external_id = #{id} AND r.canvas_id = #{canvasId}
    AND r.actor_user_id = #{userId} AND r.actor_team_id <=> #{teamId}
    AND n.status NOT IN ('SUCCEEDED','PARTIAL_FAILED','FAILED','BLOCKED','CANCELLED')
AND r.cancel_requested = FALSE AND r.deadline_at > UTC_TIMESTAMP(6)

mapper.update:
UPDATE afv_media_job SET status = 'WAITING', phase = '等待原素材接收完成', owner_instance_id = NULL,
    lease_until = NULL, next_run_at = TIMESTAMPADD(SECOND, 5, UTC_TIMESTAMP(6)),
    revision = revision + 1, updated_at = UTC_TIMESTAMP(6) WHERE id = #{id}

UPDATE afv_media_job SET status = 'CANCELLED', cancel_requested = TRUE, phase = '导入已停止', error_msg = #{message},
    checkpoint_json = #{checkpoint}, owner_instance_id = NULL, lease_until = NULL, revision = revision + 1,
    updated_at = UTC_TIMESTAMP(6) WHERE id = #{id}

UPDATE afv_media_job SET lease_until = TIMESTAMPADD(SECOND, 90, UTC_TIMESTAMP(6))
WHERE id = #{id} AND kind = 'COMFY_WORKFLOW_TEST' AND status = 'RUNNING' AND owner_instance_id = #{owner}
    AND owner_epoch = #{epoch} AND lease_until > UTC_TIMESTAMP(6)

UPDATE afv_media_job SET status = 'WAITING', phase = #{phase}, error_msg = #{error}, lease_until = NULL,
    next_run_at = TIMESTAMPADD(SECOND, #{seconds}, UTC_TIMESTAMP(6)), revision = revision + 1,
    updated_at = UTC_TIMESTAMP(6) WHERE id = #{id}

UPDATE afv_media_job SET status = 'WAITING', error_msg = NULL, lease_until = NULL,
    next_run_at = UTC_TIMESTAMP(6), deadline_at = TIMESTAMPADD(MINUTE, 60, UTC_TIMESTAMP(6)),
    revision = revision + 1, updated_at = UTC_TIMESTAMP(6) WHERE id = #{id}

UPDATE afv_media_job SET status = 'WAITING', phase = '按核实决定继续原任务', error_msg = NULL,
    next_run_at = UTC_TIMESTAMP(6), deadline_at = TIMESTAMPADD(HOUR, 2, UTC_TIMESTAMP(6)),
    revision = revision + 1, updated_at = UTC_TIMESTAMP(6) WHERE id = #{id}

UPDATE afv_media_job SET status = 'CANCELLED', phase = '管理员已核实结束', error_msg = #{message}, cancel_requested = TRUE,
    owner_instance_id = NULL, lease_until = NULL, owner_epoch = owner_epoch + 1,
    revision = revision + 1, updated_at = UTC_TIMESTAMP(6) WHERE id = #{id}
